-- Seed SOLO Units 26 & 27 student-facing resources into public.resources
-- Mirrors the inline RESOURCES object in solo/index.html (units 24/25 already seeded the same way).
-- Idempotent: clears existing GLOBAL rows for these two units first, then re-inserts.

delete from public.resources where unit_id in ('u26','u27') and scope = 'global';

